 "content": "def transform(grid):
    # Reconstruct periodic rows from the observed colored sequence. Zero cells
    # are erased portions of the patterned field; retain zeros where no row
    # pattern can be inferred.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        known = [(c, v) for c, v in enumerate(row) if v not in (0, 1, 4)]
        # infer shortest repeating sequence consistent with all known positions
        candidates = []
        for p in range(1, len(row) + 1):
            vals = {}
            ok = True
            for c, v in known:
                k = c % p
                if k in vals and vals[k] != v:
                    ok = False
                    break
                vals[k] = v
            if ok and len(vals) >= min(p, 3):
                candidates.append((p, vals))
        if not candidates:
            continue
        p, vals = min(candidates, key=lambda x: x[0])
        for c, v in enumerate(row):
            if v == 0 and c % p in vals:
                out[r][c] = vals[c % p]
    return out
"
}

